export const SOURCES: CourseSource[] = [
  { id: 'compassion-neff-definition', title: 'Kristin Neff · What is self-compassion? (self-compassion.org)', url: 'https://self-compassion.org/what-is-self-compassion/', type: 'guidance', finding: 'Neff define la autocompasión como ofrecerte a ti mismo la calidez y la comprensión que le ofrecerías a un amigo que atraviesa un momento difícil, con tres componentes: amabilidad hacia ti mismo frente a autojuicio, humanidad compartida frente a aislamiento, y atención plena frente a sobreidentificación. Distingue entre la autocompasión tierna (consolarte y aceptarte) y la autocompasión firme (actuar para protegerte, poner límites, perseguir metas o salir de situaciones dañinas), y separa la autocompasión de la autoestima, la autocompasión mal entendida como lástima de uno mismo y la indulgencia excesiva.', limitation: 'Es una definición escrita por la investigadora que desarrolló el concepto, no un estudio; explica el modelo en lugar de ponerlo a prueba. La página fue leída.' },
  { id: 'compassion-neff-exercises', title: 'Kristin Neff · Self-Compassion (2011) y ejercicios de autocompasión (self-compassion.org)', url: 'https://self-compassion.org/', type: 'technique', finding: 'Neff ofrece ejercicios prácticos para desarrollar la autocompasión, entre ellos preguntarte cómo tratarías a un amigo, la pausa de autocompasión (reconocer el dolor, recordar la humanidad compartida, ofrecerte amabilidad, a menudo con un contacto de apoyo), un diario de autocompasión y escribirte una carta desde la perspectiva de un amigo que te quiere incondicionalmente.', limitation: 'Es una guía de práctica de la creadora del concepto. Los ejercicios individuales no se han probado cada uno en ensayos; la evidencia proviene de programas que los combinan.' },
  { id: 'compassion-mindful-self-compassion-rct', title: 'Neff & Germer · 2013 · A pilot study and randomized controlled trial of the Mindful Self-Compassion program (Journal of Clinical Psychology)', url: 'https://doi.org/10.1002/jclp.21923', type: 'research', finding: 'En un ensayo aleatorizado con adultos de la comunidad, el programa de Autocompasión Consciente de ocho semanas produjo mayores aumentos en la autocompasión, la atención plena, la compasión hacia los demás y la satisfacción con la vida, y mayores descensos en la depresión, la ansiedad, el estrés y la evitación emocional, que un grupo de control en lista de espera. Las mejoras se mantuvieron en los seguimientos a los seis meses y al año, y una mayor práctica se asoció con mayores avances en la autocompasión.', limitation: 'Es un ensayo pequeño dirigido por los creadores del programa, comparado con una lista de espera y no con una alternativa activa, con medidas en su mayoría autoinformadas. Evalúa el programa completo, no ejercicios sueltos.' },
  { id: 'compassion-ferrari', title: 'Ferrari et al. · 2019 · Self-compassion interventions and psychosocial outcomes: a meta-analysis of RCTs (Mindfulness)', url: 'https://doi.org/10.1007/s12671-019-01134-6', type: 'research', finding: 'Al reunir 27 ensayos controlados aleatorizados de intervenciones de autocompasión, el metaanálisis halló mejoras en una variedad de resultados psicosociales, entre ellos la propia autocompasión, la rumiación, la autocrítica, el estrés, la depresión y la ansiedad.', limitation: 'Muchos de los ensayos incluidos eran pequeños y variaban en formato, población y condición de control; la mayoría de los resultados fueron autoinformados y los periodos de seguimiento fueron cortos.' },
  { id: 'compassion-gilbert-cft', title: 'Gilbert · 2014 · The origins and nature of compassion focused therapy (British Journal of Clinical Psychology)', url: 'https://doi.org/10.1111/bjc.12043', type: 'research', finding: 'Gilbert describe cómo se desarrolló la terapia centrada en la compasión (TCC, por sus siglas en inglés: CFT) para personas con mucha vergüenza y autocrítica que entendían la lógica de la terapia pero tenían dificultades para sentirse tranquilizadas o seguras. Se apoya en un modelo de tres sistemas de regulación emocional que interactúan: amenaza y protección, impulso y búsqueda de recursos, y calma, satisfacción y afiliación.', limitation: 'Es una revisión teórica y clínica, no un ensayo. El modelo de tres sistemas es un marco clínico simplificado, y la evidencia de la CFT como terapia todavía se está desarrollando.' },
  { id: 'compassion-gilbert-mind', title: 'Paul Gilbert · The Compassionate Mind (2009) y la Compassionate Mind Foundation', url: 'https://www.compassionatemind.co.uk/', type: 'technique', finding: 'El entrenamiento de la mente compasiva de Gilbert incluye la respiración de ritmo calmante (hacer más lenta la respiración hasta un ritmo constante y cómodo) y la imaginación de tu yo compasivo, una versión sabia, fuerte y cuidadosa de ti, como formas de activar el sistema de calma.', limitation: 'Es una guía de práctica del creador de la CFT y de su fundación. Estos ejercicios suelen enseñarse dentro de una terapia o de un entrenamiento estructurado y no se han probado aquí como autoayuda independiente.' },
  { id: 'compassion-tangney-moral-emotions', title: 'Tangney, Stuewig & Mashek · 2007 · Moral emotions and moral behavior (Annual Review of Psychology)', url: 'https://doi.org/10.1146/annurev.psych.56.091103.070145', type: 'research', finding: 'La revisión distingue la vergüenza, un enfoque doloroso en el yo completo, de la culpa, un enfoque en una conducta específica. La propensión a la culpa se asocia con la empatía y con la acción reparadora, mientras que la propensión a la vergüenza se asocia con esconderse, negar, la ira defensiva, culpar a otros y síntomas psicológicos.', limitation: 'Es sobre todo investigación correlacional sobre disposiciones (ser propenso a la vergüenza o a la culpa); no demuestra que pasar de la vergüenza a la culpa en un momento concreto cambie los resultados.' },
  { id: 'compassion-brown-shame-resilience', title: 'Brown · 2006 · Shame resilience theory: a grounded theory study on women and shame (Families in Society)', url: 'https://doi.org/10.1606/1044-3894.3483', type: 'research', finding: 'A partir de entrevistas con mujeres, el estudio describe la resiliencia a la vergüenza a lo largo de cuatro continuos: reconocer la vergüenza y comprender sus detonantes, practicar la conciencia crítica, acercarse a otras personas y hablar de la vergüenza.', limitation: 'Es investigación cualitativa, de construcción de teoría, solo con mujeres; describe patrones pero no comprueba si practicar los cuatro elementos reduce la vergüenza.' },
  { id: 'compassion-brown-practice', title: 'Brené Brown · I Thought It Was Just Me (2007) y brenebrown.com', url: 'https://brenebrown.com/', type: 'technique', finding: 'Brown distingue la vergüenza (un sentimiento doloroso de que eres defectuoso e indigno) de la culpa (malestar por algo que hiciste) y presenta la resiliencia a la vergüenza como un conjunto de habilidades: reconocer la vergüenza y sus detonantes, comprobar con la realidad los mensajes que hay detrás, acercarse a otros y hablar de la vergüenza.', limitation: 'Es un libro y un sitio web populares construidos sobre la investigación cualitativa de la autora; las prácticas no se han probado como intervención.' },
];

